/**
 * Structure ops for the visual editor: insert (from the palette), delete, duplicate, wrap, unwrap and move across
 * containers. Each one is a minimal splice of the source (byte offsets from @babel/parser, the file's own indentation),
 * re-parsed before it is accepted, and refused with a specific reason when it is unsafe: the element is generated by code
 * (a list, a condition, a prop), it is the top element of its component, or the moved / inserted code would reference a
 * name that is not in scope where it lands. Imports are kept up to date: a kit component that is inserted gets added to
 * the file's kit import (or a new import line), and one that is no longer used after a delete or unwrap is pruned.
 */
import type * as t from '@babel/types'
import { componentFor, isKitFile, isReusable, registryFor, type ComponentSchema } from './registry/registry'
import { elementByKey, importsOf, indexElements, isKitImport, jsxName, nodeAt, parseSource, tryParse, walk, type FileMap } from './source'
import { applyEdits, indentAt, lineEnd, lineStart, quoteStyle, type TextEdit } from './splice'

export interface StructSelection {
  file: string
  key: string
  part?: { prop: string; index: number } | null
}

export type WrapWith = 'Stack' | 'Box' | 'Card' | 'Grid'
export type InsertWhere = 'before' | 'after' | 'inside' | 'slot'

export type StructOp =
  | { op: 'delete' }
  | { op: 'duplicate' }
  | { op: 'wrap'; with: WrapWith }
  | { op: 'unwrap' }
  /** insert component `component` relative to the selection; `inside` appends (or puts it at child `index`); `slot` fills prop `slot` */
  | { op: 'insert'; component: string; where: InsertWhere; index?: number; slot?: string }
  /** move the selection into container `target` (same file) before its child `index` (count = at the end) */
  | { op: 'moveTo'; target: StructSelection; index: number }

export type StructResult =
  | { ok: true; patches: { path: string; before: string; after: string }[]; label: string; select?: StructSelection | null }
  | { ok: false; error: string }

const NOTHING = 'Nothing to change'
const fail = (error: string): StructResult => ({ ok: false, error })

// ── Where an element sits ───────────────────────────────────────────────────

function parentsOf(ast: t.File, node: t.Node): t.Node[] {
  let out: t.Node[] = []
  walk(ast.program, (n, parents) => {
    if (n === node) out = [...parents]
  })
  return out
}

const LIST_CALLS = new Set(['map', 'flatMap', 'filter', 'reduce', 'forEach'])

function isListCall(n: t.Node): boolean {
  return n.type === 'CallExpression' && n.callee.type === 'MemberExpression' && n.callee.property.type === 'Identifier' && LIST_CALLS.has(n.callee.property.name)
}

/** Non-blank JSX children (whitespace text and `{}` / comments skipped). */
export function childItems(el: t.JSXElement | t.JSXFragment): t.Node[] {
  return el.children.filter(
    (c) => !(c.type === 'JSXText' && !c.value.trim()) && !(c.type === 'JSXExpressionContainer' && c.expression.type === 'JSXEmptyExpression'),
  )
}

export type Place =
  | { kind: 'child'; parent: t.JSXElement | t.JSXFragment; items: t.Node[]; index: number; parents: t.Node[]; inList: boolean }
  | { kind: 'root'; parents: t.Node[]; inList: boolean }
  | { kind: 'refused'; reason: string; parents: t.Node[]; inList: boolean }

/** Whether the element (given its ancestors) is rendered once per item of a list. */
function inListOf(parents: t.Node[]): boolean {
  return parents.some((p, i) => isListCall(p) && i + 1 < parents.length && (p as t.CallExpression).arguments.includes(parents[i + 1] as t.Expression))
}

function placeOf(ast: t.File, el: t.JSXElement): Place {
  return placeFrom(el, parentsOf(ast, el))
}

/**
 * Where an element sits, given its ancestors (outermost first, as `walk` hands them over): a fixed child of JSX, the top
 * element of its component, or refused with the reason (a list template, a condition, a prop, a variable). One walk can
 * place every element of a file this way (the layers tree) instead of a walk per element.
 */
export function placeFrom(el: t.JSXElement, parents: t.Node[]): Place {
  const inList = inListOf(parents)
  const p = parents[parents.length - 1]
  if (p && (p.type === 'JSXElement' || p.type === 'JSXFragment')) {
    const items = childItems(p)
    return { kind: 'child', parent: p, items, index: items.indexOf(el), parents, inList }
  }
  let i = parents.length - 1
  while (i >= 0 && parents[i].type !== 'JSXElement' && parents[i].type !== 'JSXFragment') i--
  const between = parents.slice(i + 1)
  if (between.some(isListCall)) return { kind: 'refused', reason: 'Inside a list — it repeats for every row; edit the template with AI or code', parents, inList }
  if (between.some((n) => n.type === 'JSXAttribute')) return { kind: 'refused', reason: 'Passed in a prop — use AI or code', parents, inList }
  const holder = [...between].reverse().find((n) => n.type !== 'ParenthesizedExpression')
  if (i < 0 && (holder?.type === 'ReturnStatement' || holder?.type === 'ArrowFunctionExpression')) return { kind: 'root', parents, inList }
  if (between.some((n) => n.type === 'LogicalExpression' || n.type === 'ConditionalExpression')) {
    return { kind: 'refused', reason: 'Shown by a condition — change the condition with AI or code', parents, inList }
  }
  return { kind: 'refused', reason: 'Generated by code — use AI or code', parents, inList }
}

const TOP = 'Top element of its component — select an inner element, or change it where the component is used'

// ── Text layout ─────────────────────────────────────────────────────────────

function startsLine(src: string, pos: number): boolean {
  return src.slice(lineStart(src, pos), pos).trim() === ''
}

function ownsLines(src: string, n: t.Node): boolean {
  return startsLine(src, n.start!) && src.slice(n.end!, lineEnd(src, n.end!)).trim() === ''
}

/** The file's indent unit (the smallest indent step it uses), two spaces by default. */
export function indentUnit(src: string): string {
  if (/^\t/m.test(src)) return '\t'
  let min = Infinity
  for (const m of src.matchAll(/^( +)\S/gm)) min = Math.min(min, m[1].length)
  return ' '.repeat(Number.isFinite(min) && min > 0 && min <= 8 ? min : 2)
}

/** Re-indent every line after the first from `from` to `to` (lines not starting with `from` keep their text). */
function reindent(text: string, from: string, to: string): string {
  if (from === to) return text
  return text
    .split('\n')
    .map((line, i) => {
      if (i === 0 || !line.trim()) return line
      return line.startsWith(from) ? to + line.slice(from.length) : to + line.replace(/^[ \t]*/, '')
    })
    .join('\n')
}

/** An insertion and where in its text the inserted element starts. */
interface Ins {
  edit: TextEdit
  offset: number
}

/** Insert `text` (written at indent `from`) right before / after sibling `ref`. */
function insertBeside(src: string, ref: t.Node, text: string, from: string, after: boolean): Ins {
  if (ownsLines(src, ref)) {
    const ind = indentAt(src, ref.start!)
    const body = reindent(text, from, ind)
    if (after) return { edit: { start: ref.end!, end: ref.end!, text: `\n${ind}${body}` }, offset: 1 + ind.length }
    const ls = lineStart(src, ref.start!)
    return { edit: { start: ls, end: ls, text: `${ind}${body}\n` }, offset: ind.length }
  }
  return after ? { edit: { start: ref.end!, end: ref.end!, text }, offset: 0 } : { edit: { start: ref.start!, end: ref.start!, text }, offset: 0 }
}

/** Insert `text` as child `index` of `el` (append when index >= the child count). */
function insertInside(src: string, el: t.JSXElement, text: string, from: string, index: number): Ins | string {
  const items = childItems(el)
  if (items.some((c) => c.type === 'JSXText')) return 'It holds text — insert before or after it instead'
  if (index < items.length) return insertBeside(src, items[index], text, from, false)
  if (items.length) return insertBeside(src, items[items.length - 1], text, from, true)
  const ind = indentAt(src, el.start!)
  const inner = ind + indentUnit(src)
  const body = reindent(text, from, inner)
  const open = el.openingElement
  if (open.selfClosing || !el.closingElement) {
    const raw = src.slice(open.start!, open.end!)
    const slash = open.start! + raw.lastIndexOf('/>')
    let s = slash
    while (s > open.start! && /\s/.test(src[s - 1])) s--
    const name = jsxName(open.name)
    const t2 = `>\n${inner}${body}\n${ind}</${name}>`
    return { edit: { start: s, end: open.end!, text: t2 }, offset: 2 + inner.length }
  }
  const t2 = `\n${inner}${body}\n${ind}`
  return { edit: { start: open.end!, end: el.closingElement.start!, text: t2 }, offset: 1 + inner.length }
}

/** Remove an element: its whole line(s) when it owns them, else just its span. */
function removeEl(src: string, n: t.Node): TextEdit {
  if (ownsLines(src, n)) return { start: lineStart(src, n.start!), end: Math.min(src.length, lineEnd(src, n.end!) + 1), text: '' }
  return { start: n.start!, end: n.end!, text: '' }
}

/** Where `ins` puts its element in the result of applying `edits` (which include `ins.edit`). */
function startAfter(edits: TextEdit[], ins: Ins): number {
  const shift = edits.filter((e) => e !== ins.edit && e.end <= ins.edit.start).reduce((d, e) => d + e.text.length - (e.end - e.start), 0)
  return ins.edit.start + shift + ins.offset
}

// ── Scope ───────────────────────────────────────────────────────────────────

const SKIP = new Set(['loc', 'start', 'end', 'leadingComments', 'trailingComments', 'innerComments', 'extra', 'range', 'typeAnnotation', 'returnType', 'typeParameters', 'typeArguments'])

function bindPattern(p: t.Node | null | undefined, into: Set<string>): void {
  if (!p) return
  switch (p.type) {
    case 'Identifier':
      into.add(p.name)
      break
    case 'ObjectPattern':
      for (const x of p.properties) bindPattern(x.type === 'RestElement' ? x.argument : (x.value as t.Node), into)
      break
    case 'ArrayPattern':
      for (const x of p.elements) bindPattern(x, into)
      break
    case 'AssignmentPattern':
      bindPattern(p.left, into)
      break
    case 'RestElement':
      bindPattern(p.argument, into)
      break
    case 'TSParameterProperty':
      bindPattern(p.parameter, into)
      break
  }
}

/** Names a statement list declares (hoisting and TDZ ignored). */
function declaredIn(stmts: t.Node[], into: Set<string>): void {
  for (const s0 of stmts) {
    const s = (s0.type === 'ExportNamedDeclaration' || s0.type === 'ExportDefaultDeclaration') && s0.declaration ? s0.declaration : s0
    if (s.type === 'VariableDeclaration') for (const d of s.declarations) bindPattern(d.id, into)
    else if ((s.type === 'FunctionDeclaration' || s.type === 'ClassDeclaration') && s.id) into.add(s.id.name)
    else if (s.type === 'ImportDeclaration') for (const sp of s.specifiers) into.add(sp.local.name)
  }
}

function isFunction(n: t.Node): n is t.Function {
  return n.type === 'ArrowFunctionExpression' || n.type === 'FunctionExpression' || n.type === 'FunctionDeclaration' || n.type === 'ObjectMethod' || n.type === 'ClassMethod'
}

/** The identifiers a node reads that it does not declare itself (JSX component names count; DOM tags don't). */
export function freeIdents(root: t.Node): Set<string> {
  const out = new Set<string>()
  const visit = (n: t.Node | null | undefined, bound: Set<string>): void => {
    if (!n || typeof n !== 'object') return
    if (n.type.startsWith('TS') && n.type !== 'TSAsExpression' && n.type !== 'TSNonNullExpression' && n.type !== 'TSSatisfiesExpression' && n.type !== 'TSTypeAssertion') return
    switch (n.type) {
      case 'Identifier':
        if (!bound.has(n.name)) out.add(n.name)
        return
      case 'MemberExpression':
      case 'OptionalMemberExpression':
        visit(n.object, bound)
        if (n.computed) visit(n.property, bound)
        return
      case 'ObjectProperty':
        if (n.computed) visit(n.key, bound)
        visit(n.value, bound)
        return
      case 'JSXOpeningElement': {
        let nm: t.Node = n.name
        while (nm.type === 'JSXMemberExpression') nm = nm.object
        if (nm.type === 'JSXIdentifier' && /^[A-Z_$]/.test(nm.name) && !bound.has(nm.name)) out.add(nm.name)
        for (const a of n.attributes) visit(a.type === 'JSXAttribute' ? a.value : a.argument, bound)
        return
      }
      case 'JSXClosingElement':
      case 'JSXClosingFragment':
      case 'JSXOpeningFragment':
      case 'JSXText':
        return
      case 'BlockStatement':
      case 'Program': {
        const b = new Set(bound)
        declaredIn(n.body, b)
        for (const s of n.body) visit(s, b)
        return
      }
      case 'VariableDeclarator':
        visit(n.init, bound)
        return
      case 'FunctionDeclaration':
      case 'ClassDeclaration':
        if (n.id) bound.add(n.id.name)
        break
      case 'CatchClause': {
        const b = new Set(bound)
        bindPattern(n.param, b)
        visit(n.body, b)
        return
      }
      case 'ForStatement':
      case 'ForInStatement':
      case 'ForOfStatement': {
        const b = new Set(bound)
        const left = n.type === 'ForStatement' ? n.init : n.left
        if (left && left.type === 'VariableDeclaration') for (const d of left.declarations) bindPattern(d.id, b)
        for (const k of Object.keys(n)) if (!SKIP.has(k)) visitKey(n, k, b)
        return
      }
      case 'LabeledStatement':
        visit(n.body, bound)
        return
      case 'BreakStatement':
      case 'ContinueStatement':
        return
    }
    if (isFunction(n)) {
      const b = new Set(bound)
      if ((n.type === 'FunctionExpression' || n.type === 'FunctionDeclaration') && n.id) b.add(n.id.name)
      for (const p of n.params) bindPattern(p, b)
      for (const p of n.params) if (p.type === 'AssignmentPattern') visit(p.right, b)
      if ((n.type === 'ObjectMethod' || n.type === 'ClassMethod') && n.computed) visit(n.key, bound)
      visit(n.body, b)
      return
    }
    for (const k of Object.keys(n)) if (!SKIP.has(k)) visitKey(n, k, bound)
  }
  const visitKey = (n: t.Node, k: string, bound: Set<string>) => {
    const v = (n as unknown as Record<string, unknown>)[k]
    if (Array.isArray(v)) {
      for (const c of v) if (c && typeof c === 'object' && typeof (c as t.Node).type === 'string') visit(c as t.Node, bound)
    } else if (v && typeof v === 'object' && typeof (v as t.Node).type === 'string') visit(v as t.Node, bound)
  }
  visit(root, new Set())
  return out
}

/** Names visible at a point whose ancestors are `parents` (outermost first). */
function visibleAt(parents: t.Node[]): Set<string> {
  const out = new Set<string>()
  for (const p of parents) {
    if (p.type === 'Program' || p.type === 'BlockStatement') declaredIn(p.body, out)
    else if (isFunction(p)) {
      if ((p.type === 'FunctionExpression' || p.type === 'FunctionDeclaration') && p.id) out.add(p.id.name)
      for (const x of p.params) bindPattern(x, out)
    } else if (p.type === 'CatchClause') bindPattern(p.param, out)
    else if (p.type === 'ForStatement' || p.type === 'ForInStatement' || p.type === 'ForOfStatement') {
      const left = p.type === 'ForStatement' ? p.init : p.left
      if (left && left.type === 'VariableDeclaration') for (const d of left.declarations) bindPattern(d.id, out)
    }
  }
  return out
}

/** Every name declared anywhere in the file (a name not declared here is a global). */
function declaredAnywhere(ast: t.File): Set<string> {
  const out = new Set<string>()
  walk(ast.program, (n) => {
    if (n.type === 'Program' || n.type === 'BlockStatement') declaredIn(n.body, out)
    else if (isFunction(n)) for (const x of n.params) bindPattern(x, out)
    else if (n.type === 'CatchClause') bindPattern(n.param, out)
    else if (n.type === 'VariableDeclarator') bindPattern(n.id, out)
  })
  return out
}

const GLOBALS = new Set(['undefined', 'NaN', 'Infinity', 'Math', 'Date', 'JSON', 'Number', 'String', 'Boolean', 'Array', 'Object', 'Intl', 'console', 'window', 'document', 'React'])

// ── Imports ─────────────────────────────────────────────────────────────────

function dirname(p: string): string {
  const i = p.lastIndexOf('/')
  return i < 0 ? '' : p.slice(0, i)
}

/** A relative module specifier from `from` to `to` (extension and /index dropped). */
export function relSpec(from: string, to: string): string {
  const a = dirname(from).split('/').filter(Boolean)
  const b = to.replace(/\.(t|j)sx?$/, '').replace(/\/index$/, '').split('/')
  let i = 0
  while (i < a.length && i < b.length - 1 && a[i] === b[i]) i++
  const up = a.length - i
  return (up ? '../'.repeat(up) : './') + b.slice(i).join('/')
}

/** Where a component should be imported from in `file`: the kit index for kit components, else its own module. */
function sourceFor(file: string, comp: ComponentSchema, files: FileMap): string {
  if (isKitFile(comp.file)) {
    const kitIndex = Object.keys(files).find((p) => /(^|\/)kit\/index\.tsx?$/.test(p))
    return relSpec(file, kitIndex ? dirname(kitIndex) : 'kit')
  }
  return relSpec(file, comp.file)
}

/** Edits that import `names` (components from the registry) into `file`, merging into an existing import from the same module. */
function importEdits(files: FileMap, file: string, src: string, ast: t.File, comps: ComponentSchema[]): TextEdit[] | string {
  const have = importsOf(ast)
  const local = declaredAnywhere(ast)
  const bySource = new Map<string, string[]>()
  for (const c of comps) {
    if (c.file === file) continue
    const spec = sourceFor(file, c, files)
    const h = have.get(c.name)
    if (h) {
      if (isKitFile(c.file) ? isKitImport(h.source) : h.source === spec) continue
      return `${c.name} already means something else in this file`
    }
    if (local.has(c.name)) return `${c.name} already means something else in this file`
    bySource.set(spec, [...(bySource.get(spec) ?? []), c.name])
  }
  const edits: TextEdit[] = []
  const imports = ast.program.body.filter((s): s is t.ImportDeclaration => s.type === 'ImportDeclaration')
  const newLines: string[] = []
  const q = quoteStyle(src)
  for (const [spec, names] of bySource) {
    const kit = isKitImport(spec)
    const target = imports.find((s) => s.importKind !== 'type' && (s.source.value === spec || (kit && isKitImport(s.source.value) && /kit\/?$/.test(s.source.value))) && s.specifiers.some((x) => x.type === 'ImportSpecifier'))
    if (target) {
      const last = [...target.specifiers].reverse().find((x) => x.type === 'ImportSpecifier')!
      edits.push({ start: last.end!, end: last.end!, text: names.map((n) => `, ${n}`).join('') })
    } else newLines.push(`import { ${names.join(', ')} } from ${q}${spec}${q}`)
  }
  if (newLines.length) {
    const last = imports[imports.length - 1]
    if (last) edits.push({ start: last.end!, end: last.end!, text: newLines.map((l) => `\n${l}`).join('') })
    else edits.push({ start: 0, end: 0, text: newLines.map((l) => `${l}\n`).join('') })
  }
  return edits
}

/** Drop import specifiers among `names` that the file no longer uses (a whole import line when it empties). */
export function pruneImports(src: string, names: string[]): string {
  const ast = tryParse(src)
  if (!ast || !names.length) return src
  const used = new Set<string>()
  for (const s of ast.program.body) if (s.type !== 'ImportDeclaration') for (const n of freeIdents(s)) used.add(n)
  const edits: TextEdit[] = []
  for (const s of ast.program.body) {
    if (s.type !== 'ImportDeclaration') continue
    const dead = s.specifiers.filter((sp) => names.includes(sp.local.name) && !used.has(sp.local.name))
    if (!dead.length) continue
    if (dead.length === s.specifiers.length) {
      edits.push({ start: lineStart(src, s.start!), end: Math.min(src.length, lineEnd(src, s.end!) + 1), text: '' })
      continue
    }
    for (const sp of dead) {
      const i = s.specifiers.indexOf(sp)
      // the specifier and the comma + space after it (or, for the last one, before it)
      const next = s.specifiers[i + 1]
      const prev = s.specifiers[i - 1]
      if (next && !dead.includes(next)) edits.push({ start: sp.start!, end: next.start!, text: '' })
      else if (prev) edits.push({ start: prev.end!, end: sp.end!, text: '' })
      else edits.push({ start: sp.start!, end: sp.end!, text: '' })
    }
  }
  if (!edits.length) return src
  try {
    const out = applyEdits(src, edits)
    return tryParse(out) ? out : src
  } catch {
    return src
  }
}

/** The kit / app component names a snippet or element renders (JSX names that resolve to a registry component). */
function componentNames(files: FileMap, file: string, n: t.Node): string[] {
  const out = new Set<string>()
  walk(n, (x) => {
    if (x.type === 'JSXOpeningElement' && x.name.type === 'JSXIdentifier' && /^[A-Z]/.test(x.name.name) && componentFor(files, file, x.name.name)) out.add(x.name.name)
  })
  return [...out]
}

/** Capitalised JSX names in a node. */
function jsxNames(n: t.Node): string[] {
  const out = new Set<string>()
  walk(n, (x) => {
    if (x.type === 'JSXOpeningElement' && x.name.type === 'JSXIdentifier' && /^[A-Z]/.test(x.name.name)) out.add(x.name.name)
  })
  return [...out]
}

// ── The palette ─────────────────────────────────────────────────────────────

export interface PaletteItem {
  name: string
  file: string
  category: string
  description?: string
  kit: boolean
  /** the JSX the palette inserts */
  snippet: string
  /** why it can't be inserted from the palette (needs data or code) */
  disabled?: string
}

function parseSnippet(snippet: string): t.Expression | null {
  try {
    const ast = parseSource(`(${snippet}\n)`)
    const s = ast.program.body[0]
    return s && s.type === 'ExpressionStatement' ? s.expression : null
  } catch {
    return null
  }
}

function kitComponents(files: FileMap): Map<string, ComponentSchema> {
  return new Map(registryFor(files).components.filter((c) => isKitFile(c.file) && c.exported).map((c) => [c.name, c]))
}

/** A plain snippet from the props: required enums get their first option, required text the component's name. */
function basicSnippet(c: ComponentSchema): { snippet: string; disabled?: string } {
  const attrs: string[] = []
  for (const p of c.props) {
    if (!p.required || p.name === 'children') continue
    if (p.control === 'select' && p.options?.length) attrs.push(`${p.name}="${p.options[0]}"`)
    else if (p.control === 'text' || p.control === 'textarea') attrs.push(`${p.name}="${c.name}"`)
    else if (p.control === 'number') attrs.push(`${p.name}={${p.min ?? 0}}`)
    else if (p.control === 'boolean') attrs.push(`${p.name}={false}`)
    else if (p.control === 'event') attrs.push(`${p.name}={() => {}}`)
    else if (p.control === 'list') attrs.push(`${p.name}={[]}`)
    else return { snippet: `<${c.name} />`, disabled: `Needs ${p.name} (data or code) — ask AI to add it` }
  }
  const open = [c.name, ...attrs].join(' ')
  return { snippet: c.children ? `<${open}>${c.name}</${open.split(' ')[0]}>` : `<${open} />` }
}

/** The components the palette offers for `file`: the kit plus the app's reusable components, with their snippets. */
export function paletteFor(files: FileMap): PaletteItem[] {
  const reg = registryFor(files)
  const kit = kitComponents(files)
  const out: PaletteItem[] = []
  for (const c of reg.components) {
    const isKit = isKitFile(c.file)
    if (isKit ? !c.exported : !isReusable(files, c)) continue
    if (isKit && /^(Toaster|ColorSchemeToggle)$/.test(c.name)) continue
    let snippet: string | null = null
    let disabled: string | undefined
    if (c.example) {
      const ex = parseSnippet(c.example)
      const free = ex ? [...freeIdents(ex)].filter((n) => !kit.has(n) && n !== c.name && !GLOBALS.has(n)) : ['?']
      if (ex && !free.length) snippet = c.example.trim()
    }
    if (snippet === null) ({ snippet, disabled } = basicSnippet(c))
    out.push({ name: c.name, file: c.file, category: isKit ? (c.category ?? 'other') : 'your components', description: c.description, kit: isKit, snippet, ...(disabled ? { disabled } : {}) })
  }
  return out.sort((a, b) => a.category.localeCompare(b.category) || a.name.localeCompare(b.name))
}

// ── Containers ──────────────────────────────────────────────────────────────

const VOID = new Set(['area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'source', 'track', 'wbr', 'textarea', 'select', 'option', 'svg', 'path'])

/** Whether new elements can go inside `el`: a non-void DOM element or a component that takes children (and no text in it). */
export function acceptsChildren(files: FileMap, file: string, el: t.JSXElement): boolean {
  const name = jsxName(el.openingElement.name)
  if (childItems(el).some((c) => c.type === 'JSXText')) return false
  if (/^[a-z]/.test(name)) return !VOID.has(name)
  return !!componentFor(files, file, name)?.children
}

export interface DropTarget {
  file: string
  key: string
  vsrc: string
  /** tagged element children and their child index (the drop line is drawn between their boxes) */
  items: { vsrc: string; index: number }[]
  count: number
  start: number
  end: number
}

const targetsMemo = new WeakMap<FileMap, DropTarget[]>()

/** Every container in the app's own files that a drop can land in (not kit files, not list templates). */
export function dropTargets(files: FileMap): DropTarget[] {
  const hit = targetsMemo.get(files)
  if (hit) return hit
  const out: DropTarget[] = []
  for (const [file, src] of Object.entries(files)) {
    if (isKitFile(file) || !/\.(t|j)sx$/.test(file)) continue
    const ast = tryParse(src)
    if (!ast) continue
    walk(ast.program, (n, parents) => {
      if (n.type !== 'JSXElement' || !acceptsChildren(files, file, n)) return
      // a list template's root repeats per row: not a drop target
      const p = parents[parents.length - 1]
      if (p && p.type !== 'JSXElement' && p.type !== 'JSXFragment' && inListOf(parents)) return
      const key = indexElements(ast).find((e) => e.node === n)?.key
      if (!key) return
      const items = childItems(n)
      out.push({
        file,
        key,
        vsrc: `${file}:${n.loc!.start.line}:${n.loc!.start.column + 1}`,
        items: items.flatMap((c, index) => (c.type === 'JSXElement' ? [{ vsrc: `${file}:${c.loc!.start.line}:${c.loc!.start.column + 1}`, index }] : [])),
        count: items.length,
        start: n.start!,
        end: n.end!,
      })
    })
  }
  targetsMemo.set(files, out)
  return out
}

// ── Ops ─────────────────────────────────────────────────────────────────────

const WRAPPERS: Record<WrapWith, string> = {
  Stack: 'flex flex-col gap-3',
  Box: '',
  Card: 'rounded-xl p-4 shadow-sm',
  Grid: 'grid gap-4',
}

function label(name: string, op: StructOp): string {
  switch (op.op) {
    case 'delete':
      return `${name}: delete`
    case 'duplicate':
      return `${name}: duplicate`
    case 'wrap':
      return `${name}: wrap in ${op.with}`
    case 'unwrap':
      return `${name}: unwrap`
    case 'insert':
      return `add ${op.component}`
    case 'moveTo':
      return `${name}: move`
  }
}

/** Apply a structure op to the selected element. Never throws. */
export function applyStructOp(files: FileMap, sel: StructSelection, op: StructOp): StructResult {
  try {
    return inner(files, sel, op)
  } catch (e) {
    return fail(e instanceof Error ? e.message : String(e))
  }
}

function inner(files: FileMap, sel: StructSelection, op: StructOp): StructResult {
  const src = files[sel.file]
  const ast = src == null ? null : tryParse(src)
  const hit = ast && elementByKey(ast, sel.key)
  if (!ast || !hit) return fail('The element is no longer in the source')
  if (isKitFile(sel.file)) return fail('Kit source is sealed — change it through props')
  const el = hit.node
  const place = placeOf(ast, el)
  const name = hit.name
  const u = indentUnit(src)

  /** Apply edits (+ prune `prune` imports), re-parse, and select the element starting at `at` (or `selectKeyOf`). */
  const finish = (edits: TextEdit[], at: number | null, prune: string[] = []): StructResult => {
    if (!edits.length) return fail(NOTHING)
    let out = applyEdits(src, edits)
    const parsed = tryParse(out)
    if (!parsed) return fail('That edit would break the file; use AI or code')
    let select: StructSelection | null = null
    if (at !== null) {
      const n = nodeAt(parsed, at, 'JSXElement')
      const key = n && indexElements(parsed).find((e) => e.node === n)?.key
      if (key) select = { file: sel.file, key, part: null }
    }
    out = pruneImports(out, prune)
    if (out === src) return fail(NOTHING)
    return { ok: true, patches: [{ path: sel.file, before: src, after: out }], label: label(name, op), select }
  }
  const parentStart = (): number | null => (place.kind === 'child' && place.parent.type === 'JSXElement' ? place.parent.start! : null)

  switch (op.op) {
    case 'delete': {
      if (place.kind === 'root') return fail(TOP)
      if (place.kind === 'refused') return fail(place.reason)
      return finish([removeEl(src, el)], parentStart(), componentNames(files, sel.file, el))
    }
    case 'duplicate': {
      if (place.kind === 'root') return fail(TOP)
      if (place.kind === 'refused') return fail(place.reason)
      if (place.inList) return fail('Inside a list — the rows come from data; add data instead of copying the template')
      let copy = src.slice(el.start!, el.end!)
      // a literal key / id must stay unique
      const fixes: TextEdit[] = []
      for (const a of el.openingElement.attributes) {
        if (a.type !== 'JSXAttribute' || a.name.type !== 'JSXIdentifier' || !/^(key|id)$/.test(a.name.name) || a.value?.type !== 'StringLiteral') continue
        const end = a.value.end! - 1 - el.start!
        fixes.push({ start: end, end, text: '-2' })
      }
      copy = applyEdits(copy, fixes)
      const ins = insertBeside(src, el, copy, indentAt(src, el.start!), true)
      return finish([ins.edit], startAfter([ins.edit], ins))
    }
    case 'wrap': {
      if (place.kind === 'refused') return fail(place.reason)
      const kit = kitComponents(files)
      const comp = kit.get(op.with)
      const cls = WRAPPERS[op.with]
      const open = comp ? `<${op.with}>` : cls ? `<div className="${cls}">` : '<div>'
      const close = comp ? `</${op.with}>` : '</div>'
      const edits: TextEdit[] = []
      let at: number
      if (ownsLines(src, el)) {
        const ind = indentAt(src, el.start!)
        const ls = lineStart(src, el.start!)
        edits.push({ start: ls, end: ls, text: `${ind}${open}\n${u}` })
        at = ls + ind.length
        for (let p = src.indexOf('\n', el.start!); p >= 0 && p < el.end!; p = src.indexOf('\n', p + 1)) {
          if (src.slice(p + 1, lineEnd(src, p + 1)).trim()) edits.push({ start: p + 1, end: p + 1, text: u })
        }
        edits.push({ start: el.end!, end: el.end!, text: `\n${ind}${close}` })
      } else {
        edits.push({ start: el.start!, end: el.start!, text: open }, { start: el.end!, end: el.end!, text: close })
        at = el.start!
      }
      if (comp) {
        const imp = importEdits(files, sel.file, src, ast, [comp])
        if (typeof imp === 'string') return fail(imp)
        edits.push(...imp)
        at += imp.filter((e) => e.end <= at).reduce((d, e) => d + e.text.length - (e.end - e.start), 0)
      }
      return finish(edits, at)
    }
    case 'unwrap': {
      if (place.kind === 'refused') return fail(place.reason)
      const items = childItems(el)
      if (items.length !== 1 || (items[0].type !== 'JSXElement' && items[0].type !== 'JSXFragment')) {
        return fail(items.length ? 'Unwrap needs exactly one element inside' : 'Nothing inside to keep')
      }
      if (place.kind === 'root' && items[0].type === 'JSXFragment') return fail(TOP)
      for (const a of el.openingElement.attributes) {
        if (a.type === 'JSXSpreadAttribute') return fail('It takes props from a spread ({...}) — use AI or code')
        const an = a.name.type === 'JSXIdentifier' ? a.name.name : ''
        if (/^on[A-Z]/.test(an) || an === 'key' || an === 'ref') return fail(`Its ${an} would be lost — use AI or code`)
      }
      const child = items[0]
      const text = reindent(src.slice(child.start!, child.end!), indentAt(src, child.start!), indentAt(src, el.start!))
      return finish([{ start: el.start!, end: el.end!, text }], el.start!, componentNames(files, sel.file, { ...el, children: [] } as t.JSXElement))
    }
    case 'insert': {
      const item = paletteFor(files).find((p) => p.name === op.component)
      if (!item) return fail(`${op.component} is not in the palette`)
      if (item.disabled) return fail(item.disabled)
      const snip = parseSnippet(item.snippet)
      if (!snip) return fail(`The ${op.component} example does not parse`)
      const reg = registryFor(files)
      const kit = kitComponents(files)
      const own = reg.components.find((c) => c.name === item.name && c.file === item.file)!
      const needed = jsxNames(snip).map((n) => (n === item.name ? own : kit.get(n))).filter((c): c is ComponentSchema => !!c)
      if (!needed.includes(own)) needed.push(own)
      const imp = importEdits(files, sel.file, src, ast, needed)
      if (typeof imp === 'string') return fail(imp)
      let ins: Ins | string
      if (op.where === 'before' || op.where === 'after') {
        if (place.kind === 'root') return fail(`${TOP} (or insert inside it)`)
        if (place.kind === 'refused') return fail(place.reason)
        ins = insertBeside(src, el, item.snippet, '', op.where === 'after')
      } else if (op.where === 'inside') {
        if (place.kind === 'refused' && place.inList) return fail(place.reason)
        if (!acceptsChildren(files, sel.file, el)) return fail(`${name} doesn't take children here — insert before or after it`)
        ins = insertInside(src, el, item.snippet, '', op.index ?? Infinity)
      } else {
        const slot = op.slot ?? ''
        const a = el.openingElement.attributes.find((x): x is t.JSXAttribute => x.type === 'JSXAttribute' && x.name.type === 'JSXIdentifier' && x.name.name === slot)
        if (!a) {
          const pos = el.openingElement.name.end!
          ins = { edit: { start: pos, end: pos, text: ` ${slot}={${item.snippet}}` }, offset: slot.length + 3 }
        } else if (a.value?.type === 'JSXExpressionContainer' && a.value.expression.type === 'JSXFragment') {
          const f = a.value.expression
          ins = { edit: { start: f.closingFragment.start!, end: f.closingFragment.start!, text: item.snippet }, offset: 0 }
        } else if (a.value?.type === 'JSXExpressionContainer' && a.value.expression.type === 'JSXElement') {
          const x = a.value.expression
          ins = { edit: { start: x.start!, end: x.end!, text: `<>${src.slice(x.start!, x.end!)}${item.snippet}</>` }, offset: 2 + (x.end! - x.start!) }
        } else return fail(`${slot} is filled by code — use AI or code`)
      }
      if (typeof ins === 'string') return fail(ins)
      // the snippet must not read names that don't exist where it lands
      const free = [...freeIdents(snip)].filter((n) => !GLOBALS.has(n) && !needed.some((c) => c.name === n))
      if (free.length) {
        const vis = visibleAt([...parentsOf(ast, el), el])
        const missing = free.filter((n) => !vis.has(n))
        if (missing.length) return fail(`The example uses ${missing.join(', ')}, which isn't available here`)
      }
      const edits = [...imp, ins.edit]
      return finish(edits, startAfter(edits, ins))
    }
    case 'moveTo': {
      if (place.kind === 'root') return fail(TOP)
      if (place.kind === 'refused') return fail(place.reason)
      if (op.target.file !== sel.file) return fail('Moving to another file is not supported yet — use AI to extract it')
      const tgt = elementByKey(ast, op.target.key)
      if (!tgt) return fail('The drop target is no longer in the source')
      const tn = tgt.node
      if (tn.start! >= el.start! && tn.end! <= el.end!) return fail("Can't move an element into itself")
      if (!acceptsChildren(files, sel.file, tn)) return fail(`${tgt.name} doesn't take children`)
      const tPlace = placeOf(ast, tn)
      if (tPlace.kind === 'refused' && tPlace.inList) return fail('That container repeats for every row — use AI or code')
      if (place.parent === tn && (op.index === place.index || op.index === place.index + 1)) return fail(NOTHING)
      const tParents = [...tPlace.parents, tn]
      const vis = visibleAt(tParents)
      const all = declaredAnywhere(ast)
      const missing = [...freeIdents(el)].filter((n) => all.has(n) && !vis.has(n))
      if (missing.length) return fail(`Uses ${missing.join(', ')}, which isn't available there — use AI or code`)
      const ins = insertInside(src, tn, src.slice(el.start!, el.end!), indentAt(src, el.start!), op.index)
      if (typeof ins === 'string') return fail(ins)
      const rm = removeEl(src, el)
      const edits = [rm, ins.edit]
      return finish(edits, startAfter(edits, ins))
    }
  }
}

/**
 * Where the selected element can be dragged to: the containers of its own file outside itself, and the tag of its parent
 * (a drop there is a reorder among siblings). Empty when it can't move at all.
 */
export function dragTargetsFor(files: FileMap, sel: StructSelection): { parent: string | null; targets: DropTarget[] } {
  const src = files[sel.file]
  const ast = src == null ? null : tryParse(src)
  const hit = ast && elementByKey(ast, sel.key)
  if (!ast || !hit || isKitFile(sel.file)) return { parent: null, targets: [] }
  const place = placeOf(ast, hit.node)
  if (place.kind !== 'child') return { parent: null, targets: [] }
  const el = hit.node
  const p = place.parent
  const parent = p.type === 'JSXElement' ? `${sel.file}:${p.loc!.start.line}:${p.loc!.start.column + 1}` : null
  return { parent, targets: dropTargets(files).filter((d) => d.file === sel.file && !(d.start >= el.start! && d.end <= el.end!)) }
}
